<?php foreach($daftar as $r): $filter_status=($r['status']==='disetujui'||(int)$r['tahap']>=4)?'selesai':($r['status']==='diajukan'?'baru':((int)$r['tahap']===2?'perbaikan':'review'));?><tr data-filter-status="<?= $filter_status ?>"><td data-label="Nomor Registrasi"><div><span class="pl-no"><?= htmlspecialchars($r['nik']?:'—') ?></span><small class="pl-sub"><?= date('d/m/Y',strtotime($r['created_at'])) ?></small></div></td><td data-label="Pemohon"><div><span class="pl-nama"><?= htmlspecialchars($r['nama_pemohon']) ?></span><small class="pl-sub"><?= htmlspecialchars($r['no_permohonan']) ?></small></div></td><td data-label="Status"><span class="badge <?= $r['status'] ?>"><?= htmlspecialchars($r['status_rinci'] ?? pbg_status_label($r['status'], $r['tahap'])) ?></span></td><td data-label="Aksi"><select class="aksi-select" onchange="pbgAksi(this)">
