</select><?php if($r['status']!=='diajukan'):?><span class="locked">Terkunci</span><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div>
<script>
let pbgFilter='semua';function pbgTerapkanFilter(){let x=q.value.toLowerCase();document.querySelectorAll('#table tbody tr[data-filter-status]').forEach(r=>r.style.display=(r.innerText.toLowerCase().includes(x)&&(pbgFilter==='semua'||r.dataset.filterStatus===pbgFilter))?'':'none')}q.oninput=pbgTerapkanFilter;document.querySelectorAll('.pbg-status-filter button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.pbg-status-filter button').forEach(x=>x.classList.remove('active'));b.classList.add('active');pbgFilter=b.dataset.filter;pbgTerapkanFilter()});
function pbgAksi(sel){
  var opt=sel.options[sel.selectedIndex];
  if(!opt.value) return;
  if(opt.dataset.confirm && !confirm(opt.dataset.confirm)){ sel.selectedIndex=0; return; }
  if(opt.dataset.blank){ window.open(opt.value,'_blank'); }
  else { location.href=opt.value; }
  sel.selectedIndex=0;
}
</script>
